CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL CHECK(kind IN('news','event')), title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', when_text TEXT NOT NULL DEFAULT '', place TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (date('now')));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(ip TEXT PRIMARY KEY, n INTEGER NOT NULL, t INTEGER NOT NULL);
